DROP TABLE IF EXISTS `auth_refresh_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `auth_refresh_sessions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `teacher_id` bigint NOT NULL,
  `student_id` bigint DEFAULT NULL,
  `audience` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ADMIN or LEARNING',
  `token_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` timestamp NOT NULL,
  `revoked_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_AUTH_REFRESH_SESSIONS_TOKEN_HASH` (`token_hash`),
  KEY `FK_AUTH_REFRESH_SESSIONS_TEACHER` (`teacher_id`),
  KEY `FK_AUTH_REFRESH_SESSIONS_STUDENT` (`student_id`),
  CONSTRAINT `FK_AUTH_REFRESH_SESSIONS_STUDENT` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),
  CONSTRAINT `FK_AUTH_REFRESH_SESSIONS_TEACHER` FOREIGN KEY (`teacher_id`) REFERENCES `teachers` (`id`),
  CONSTRAINT `CHK_AUTH_REFRESH_SESSIONS_AUDIENCE` CHECK ((((`audience` = _utf8mb4'ADMIN') and (`student_id` is null)) or ((`audience` = _utf8mb4'LEARNING') and (`student_id` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

