DROP TABLE IF EXISTS `daily_curriculums`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_curriculums` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Enum: NOT_STARTED, IN_PROGRESS, COMPLETED',
  `created_at` timestamp NOT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `not_started_student_id` bigint GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'NOT_STARTED') then `student_id` else NULL end)) STORED,
  `in_progress_student_id` bigint GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'IN_PROGRESS') then `student_id` else NULL end)) STORED,
  `source_test_curriculum_id` bigint DEFAULT NULL,
  `review_status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_REQUIRED',
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `reviewed_by_teacher_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UQ_DAILY_CURRICULUMS_NOT_STARTED_STUDENT` (`not_started_student_id`),
  UNIQUE KEY `UQ_DAILY_CURRICULUMS_IN_PROGRESS_STUDENT` (`in_progress_student_id`),
  UNIQUE KEY `UQ_DAILY_CURRICULUMS_SOURCE_TEST` (`source_test_curriculum_id`),
  KEY `FK_DAILY_CURRICULUMS_STUDENT` (`student_id`),
  KEY `FK_DAILY_CURRICULUMS_REVIEWED_BY_TEACHER` (`reviewed_by_teacher_id`),
  CONSTRAINT `FK_DAILY_CURRICULUMS_REVIEWED_BY_TEACHER` FOREIGN KEY (`reviewed_by_teacher_id`) REFERENCES `teachers` (`id`),
  CONSTRAINT `FK_DAILY_CURRICULUMS_SOURCE_TEST` FOREIGN KEY (`source_test_curriculum_id`) REFERENCES `test_curriculums` (`id`),
  CONSTRAINT `FK_DAILY_CURRICULUMS_STUDENT` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=310391 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

