/*!40000 ALTER TABLE `gaze_analysis_results` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `gaze_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gaze_sessions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `test_id` bigint DEFAULT NULL,
  `training_id` bigint DEFAULT NULL,
  `story_id` bigint DEFAULT NULL,
  `content_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'TEST, TRAINING, STORY',
  `started_at` timestamp NOT NULL,
  `ended_at` timestamp NULL DEFAULT NULL,
  `data_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '초당 5~10프레임 수집 데이터를 저장한 파일 URL',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'READY, RUNNING, COMPLETED, FAILED',
  `calibration_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'NOT_STARTED, SUCCESS, FAILED, SKIPPED',
  `created_at` timestamp NOT NULL,
  PRIMARY KEY (`id`),
  KEY `FK_GAZE_SESSIONS_STUDENT` (`student_id`),
  KEY `FK_GAZE_SESSIONS_TEST` (`test_id`),
  KEY `FK_GAZE_SESSIONS_TRAINING` (`training_id`),
  KEY `FK_GAZE_SESSIONS_STORY` (`story_id`),
  CONSTRAINT `FK_GAZE_SESSIONS_STORY` FOREIGN KEY (`story_id`) REFERENCES `stories` (`id`),
  CONSTRAINT `FK_GAZE_SESSIONS_STUDENT` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),
  CONSTRAINT `FK_GAZE_SESSIONS_TEST` FOREIGN KEY (`test_id`) REFERENCES `tests` (`id`),
  CONSTRAINT `FK_GAZE_SESSIONS_TRAINING` FOREIGN KEY (`training_id`) REFERENCES `trainings` (`id`),
  CONSTRAINT `CHK_GAZE_SESSIONS_CONTENT` CHECK ((((`content_type` = _utf8mb4'TEST') and (`test_id` is not null) and (`training_id` is null) and (`story_id` is null)) or ((`content_type` = _utf8mb4'TRAINING') and (`test_id` is null) and (`training_id` is not null) and (`story_id` is null)) or ((`content_type` = _utf8mb4'STORY') and (`test_id` is null) and (`training_id` is null) and (`story_id` is not null))))
) ENGINE=InnoDB AUTO_INCREMENT=723086 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `gaze_sessions` WRITE;
