UNLOCK TABLES;
DROP TABLE IF EXISTS `reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `reports` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `start_date` timestamp NOT NULL COMMENT '리포트 기간 시작',
  `end_date` timestamp NOT NULL COMMENT '리포트 기간 종료',
  `snapshot_data` json DEFAULT NULL,
  `teacher_memo` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL COMMENT '생성일',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UQ_REPORTS_STUDENT_PERIOD` (`student_id`,`start_date`,`end_date`),
  CONSTRAINT `FK_REPORTS_STUDENT` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),
  CONSTRAINT `CHK_REPORTS_PERIOD` CHECK ((`start_date` <= `end_date`))
) ENGINE=InnoDB AUTO_INCREMENT=370033 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `reports` WRITE;
