CREATE TABLE `stories` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `story_template_id` bigint NOT NULL,
  `created_at` timestamp NOT NULL,
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Enum: IN_PROGRESS, COMPLETED, DELETED',
  `progress` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '이야기 진행률 0~100',
  PRIMARY KEY (`id`),
  KEY `FK_STORIES_STUDENT` (`student_id`),
  KEY `FK_STORIES_STORY_TEMPLATE` (`story_template_id`),
  CONSTRAINT `FK_STORIES_STORY_TEMPLATE` FOREIGN KEY (`story_template_id`) REFERENCES `story_templates` (`id`),
  CONSTRAINT `FK_STORIES_STUDENT` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),
  CONSTRAINT `CHK_STORIES_PROGRESS` CHECK ((`progress` between 0 and 100))
) ENGINE=InnoDB AUTO_INCREMENT=280005 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
