CREATE TABLE `story_lines` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `scene_id` bigint NOT NULL,
  `has_choices` tinyint(1) NOT NULL,
  `content` json NOT NULL COMMENT '대사 본문과 형태소·G2P 분석 결과',
  `branch_prompt` json DEFAULT NULL COMMENT 'AI가 생성한 분기 선택지 3개',
  `sequence_no` int NOT NULL,
  `created_at` timestamp NOT NULL,
  `read_at` timestamp NULL DEFAULT NULL,
  `revision` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_STORY_LINES_SEQUENCE` (`scene_id`,`sequence_no`),
  CONSTRAINT `FK_STORY_LINES_SCENE` FOREIGN KEY (`scene_id`) REFERENCES `story_scenes` (`scene_id`)
) ENGINE=InnoDB AUTO_INCREMENT=282134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
