DROP TABLE IF EXISTS `story_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `story_templates` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'AI에게 제공하는 이야기 컨텍스트',
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `story_templates` WRITE;
/*!40000 ALTER TABLE `story_templates` DISABLE KEYS */;
INSERT INTO `story_templates` VALUES (1,'토끼와 거북이','숲 속 동물들이 지켜보는 가운데 거만한 토끼와 느린 거북이가 산봉우리까지 달리기 시합을 한다. 토끼는 중간에 자만해 잠을 자고, 거북이는 쉬지 않고 한 걸음씩 걸어 결승선에 먼저 닿는다. 꾸준함과 끝까지 포기하지 않는 마음을 전하는 에이소프 우화. 분기 지점에서 아이에게 다음 행동을 물어본다.',NULL),(2,'개미와 배짱이','여름 내내 알뜰히 먹이를 모으는 부지런한 개미와 노래만 부르며 놀고 먹는 배짱이. 추운 겨울이 오자 배짱이가 배고파져 개미를 찾아가 도움을 청하고, 미리 준비하는 습관의 소중함을 깨닫는다. 성실과 준비를 다룬 에이소프 우화. 분기 지점에서 아이에게 다음 행동을 물어본다.',NULL),(3,'노인과 바다','바다를 평생 벗으로 여기는 늙은 어부가 며칠간의 사투 끝에 자신보다 큰 물고기를 낚는다. 돌아오는 길에 상어 떼와 맞서며, 끝내 포기하지 않는 끈기와 자연에 대한 존경을 아이의 눈높이로 그린 바다 모험. 분기 지점에서 아이에게 다음 행동을 물어본다.',NULL),(4,'신데렐라','계모와 언니들에게 심부름만 하며 사는 착한 신데렐라. 무도회 날 요정 할머니의 마법으로 예쁜 옷과 유리구두를 받고 무도회에 가 왕자와 춤을 춘다. 친절과 꿈을 잃지 않는 마음을 주제로 한 동화. 분기 지점에서 아이에게 다음 행동을 물어본다.',NULL),(5,'별주부전','병든 용왕을 위해 토끼의 간을 구하러 육지로 온 별주부. 꾀 많은 토끼에게 속았다가 다시 지혜를 짜내는 별주부와 토끼의 말재주 대결을 그린 한국 전래동화. 속임수와 지혜, 얄미운 잔꾀가 얽힌다. 분기 지점에서 아이에게 다음 행동을 물어본다.',NULL),(6,'아기돼지 삼형제','각기 짚, 나무, 벽돌로 집을 짓는 아기돼지 삼형제. 무서운 늑대가 불어와 짚과 나무집을 무너뜨리지만, 성실히 지은 벽돌집에 피신한 형제들이 꾀로 늑대를 물리친다. 부지런함과 대비를 다룬 영미 동화. 분기 지점에서 아이에게 다음 행동을 물어본다.',NULL);
/*!40000 ALTER TABLE `story_templates` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `student_feature_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_feature_profiles` (
  `id` bigint NOT NULL,
  `student_id` bigint NOT NULL,
  `reading_features_id` bigint NOT NULL,
  `accuracy_rate` decimal(5,4) DEFAULT NULL COMMENT '0~1',
  `avg_pronunciation_scor` int DEFAULT NULL COMMENT '0~1000',
  `pronunciation_error_rate` decimal(8,2) DEFAULT NULL,
  `avg_fixation_duration_ms` int DEFAULT NULL,
  `avg_fixation_count` decimal(8,2) DEFAULT NULL,
  `avg_regression_count` decimal(8,2) DEFAULT NULL,
  `skip_rate` decimal(5,2) DEFAULT NULL COMMENT '0~1',
  `avg_reading_time_ms` int DEFAULT NULL,
  `weakness_score` int DEFAULT NULL COMMENT '0~1000',
  `confidence` decimal(5,4) NOT NULL COMMENT '0~1',
  `evidence_count` int DEFAULT NULL,
  `last_evidence_at` timestamp NULL DEFAULT NULL,
  `analyzed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK_STUDENT_FEATURE_PROFILES_STUDENT` (`student_id`),
  KEY `FK_STUDENT_FEATURE_PROFILES_READING_FEATURE` (`reading_features_id`),
  CONSTRAINT `FK_STUDENT_FEATURE_PROFILES_READING_FEATURE` FOREIGN KEY (`reading_features_id`) REFERENCES `reading_features` (`id`),
  CONSTRAINT `FK_STUDENT_FEATURE_PROFILES_STUDENT` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `student_feature_profiles` WRITE;
/*!40000 ALTER TABLE `student_feature_profiles` DISABLE KEYS */;
