/*!40000 ALTER TABLE `trainings` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `word_attempt_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `word_attempt_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `word_id` bigint NOT NULL COMMENT '단어 기본형',
  `story_line_id` bigint DEFAULT NULL,
  `training_id` bigint DEFAULT NULL,
  `test_id` bigint DEFAULT NULL,
  `use_location` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Enum: TEST, TRAINING, STORY',
  `surface_text` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '문장 안에서 사용된 단어 형태',
  `has_gaze_data` tinyint(1) NOT NULL DEFAULT '0' COMMENT '시선 사용 여부',
  `has_audio_data` tinyint(1) NOT NULL,
  `fixation_duration_ms` int DEFAULT NULL,
  `fixation_count` int DEFAULT NULL,
  `gaze_start_offset_ms` int DEFAULT NULL,
  `gaze_end_offset_ms` int DEFAULT NULL,
  `is_skipped` tinyint(1) DEFAULT NULL,
  `regression_count` int DEFAULT NULL,
  `pronunciation_accuracy_score` int DEFAULT NULL COMMENT 'Azure 단어별 AccuracyScore x 10 (0~1000)',
  `speech_start_offset_ms` int DEFAULT NULL,
  `speech_end_offset_ms` int DEFAULT NULL,
  `is_correct` tinyint(1) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `total_score` int DEFAULT NULL COMMENT '발음·시선·읽기 수행 종합 단어 점수 0~1000',
  `question_no` int DEFAULT NULL COMMENT '1부터 시작',
  `target_index` int DEFAULT NULL COMMENT '0부터 시작',
  `token_index` int DEFAULT NULL COMMENT '0부터 시작',
  `is_final` tinyint(1) NOT NULL DEFAULT '1' COMMENT '같은 문항·대상·토큰 위치의 최종 시도',
  PRIMARY KEY (`id`),
  KEY `FK_WORD_ATTEMPT_LOGS_STUDENT` (`student_id`),
  KEY `FK_WORD_ATTEMPT_LOGS_WORD` (`word_id`),
  KEY `FK_WORD_ATTEMPT_LOGS_STORY_LINE` (`story_line_id`),
  KEY `FK_WORD_ATTEMPT_LOGS_TRAINING` (`training_id`),
  KEY `FK_WORD_ATTEMPT_LOGS_TEST` (`test_id`),
  CONSTRAINT `FK_WORD_ATTEMPT_LOGS_STORY_LINE` FOREIGN KEY (`story_line_id`) REFERENCES `story_lines` (`id`),
  CONSTRAINT `FK_WORD_ATTEMPT_LOGS_STUDENT` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`),
  CONSTRAINT `FK_WORD_ATTEMPT_LOGS_TEST` FOREIGN KEY (`test_id`) REFERENCES `tests` (`id`),
  CONSTRAINT `FK_WORD_ATTEMPT_LOGS_TRAINING` FOREIGN KEY (`training_id`) REFERENCES `trainings` (`id`),
  CONSTRAINT `FK_WORD_ATTEMPT_LOGS_WORD` FOREIGN KEY (`word_id`) REFERENCES `words` (`id`),
  CONSTRAINT `CHK_WORD_ATTEMPT_LOGS_LOCATION` CHECK ((((`use_location` = _utf8mb4'TEST') and (`test_id` is not null) and (`training_id` is null) and (`story_line_id` is null)) or ((`use_location` = _utf8mb4'TRAINING') and (`test_id` is null) and (`training_id` is not null) and (`story_line_id` is null)) or ((`use_location` = _utf8mb4'STORY') and (`test_id` is null) and (`training_id` is null) and (`story_line_id` is not null)))),
  CONSTRAINT `CHK_WORD_ATTEMPT_LOGS_PRONUNCIATION_ACCURACY_SCORE` CHECK (((`pronunciation_accuracy_score` is null) or (`pronunciation_accuracy_score` between 0 and 1000))),
  CONSTRAINT `CHK_WORD_ATTEMPT_LOGS_QUESTION_NO` CHECK (((`question_no` is null) or (`question_no` >= 1))),
  CONSTRAINT `CHK_WORD_ATTEMPT_LOGS_TARGET_INDEX` CHECK (((`target_index` is null) or (`target_index` >= 0))),
  CONSTRAINT `CHK_WORD_ATTEMPT_LOGS_TOKEN_INDEX` CHECK (((`token_index` is null) or (`token_index` >= 0))),
  CONSTRAINT `CHK_WORD_ATTEMPT_LOGS_TOTAL_SCORE` CHECK ((`total_score` between 0 and 1000))
) ENGINE=InnoDB AUTO_INCREMENT=381441 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `word_attempt_logs` WRITE;
